from concurrent.futures import ThreadPoolExecutor
import threading
import time

import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        self.n = n


def check(x: int) -> int:
    if x % 2 == 1:
        raise Bad(x)
    return x


def all_even(xs: list[int]) -> list[int]:
    """Run check on every element of xs in parallel using a thread pool.

    Returns the checked values in input order when all elements pass.
    If any element is bad, raises the Bad of the lowest-index bad element,
    regardless of which thread finishes first.
    """
    if not xs:
        return []
    with ThreadPoolExecutor(max_workers=len(xs)) as pool:
        futures = [pool.submit(check, x) for x in xs]
        results: list[int] = []
        first_bad: Bad | None = None
        for f in futures:
            try:
                results.append(f.result())
            except Bad as e:
                if first_bad is None:
                    first_bad = e
        if first_bad is not None:
            raise first_bad
        return results


def test_all_even_returns_values_in_order() -> None:
    assert all_even([2, 4, 6, 8]) == [2, 4, 6, 8]


def test_all_even_empty() -> None:
    assert all_even([]) == []


def test_all_even_single_bad() -> None:
    with pytest.raises(Bad) as ei:
        all_even([2, 4, 7, 8])
    assert ei.value.n == 7


def test_all_even_raises_lowest_index_bad() -> None:
    with pytest.raises(Bad) as ei:
        all_even([2, 9, 4, 3, 5])
    assert ei.value.n == 9


def test_all_even_lowest_index_not_lowest_value() -> None:
    with pytest.raises(Bad) as ei:
        all_even([4, 11, 1, 3])
    assert ei.value.n == 11


def test_all_even_lowest_index_when_later_finishes_first(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """The earlier bad element is slow; the later one finishes first."""
    later_done = threading.Event()

    def slow_check(x: int) -> int:
        if x == 1:
            # Lowest-index bad element: wait until the later one has finished.
            later_done.wait(timeout=2)
            time.sleep(0.05)
            raise Bad(x)
        if x == 3:
            try:
                raise Bad(x)
            finally:
                later_done.set()
        return x

    monkeypatch.setitem(all_even.__globals__, "check", slow_check)
    with pytest.raises(Bad) as ei:
        all_even([2, 1, 4, 3])
    assert ei.value.n == 1


def test_all_even_checks_every_element_in_parallel(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """All workers must run concurrently: a barrier only passes if they do."""
    n = 4
    barrier = threading.Barrier(n, timeout=2)

    def barrier_check(x: int) -> int:
        barrier.wait()
        return x

    monkeypatch.setitem(all_even.__globals__, "check", barrier_check)
    assert all_even([0, 2, 4, 6]) == [0, 2, 4, 6]


def test_all_even_negative_odd() -> None:
    with pytest.raises(Bad) as ei:
        all_even([2, -3, 5])
    assert ei.value.n == -3

